import math
import re
import numpy as np
from wordfreq import word_frequency
from difflib import SequenceMatcher
import statistics

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were "
    "be been being it its this that these those i you he she we they me him her us them my your "
    "his their our not no so do does did have has had will would can could should may might must "
    "about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _word_surprisal(word):
    p = word_frequency(word, "en")
    if p > 0:
        return -math.log2(p)
    return 24.0

def insertion_positional_aptness(text, anchor):
    if not (text and anchor):
        return 0.5
    anchor_toks = _content(anchor)
    text_toks = _content(text)
    if not text_toks or not anchor_toks:
        return 0.5
    matcher = SequenceMatcher(None, anchor_toks, text_toks)
    opcodes = matcher.get_opcodes()
    if not opcodes:
        return 0.5
    insert_positions = []
    for op, a_start, a_end, b_start, b_end in opcodes:
        if op == "insert":
            insert_positions.append((b_start, b_end))
    if not insert_positions:
        return 0.5
    insert_aptness_scores = []
    for b_start, b_end in insert_positions:
        position = b_start / max(1, len(text_toks))
        mid_weight = math.exp(-4.0 * (position - 0.5) ** 2)
        distance_to_left_anchor = b_start
        distance_to_right_anchor = len(text_toks) - b_end
        distance_penalty = 0.3 / (1.0 + min(distance_to_left_anchor, distance_to_right_anchor))
        position_aptness = 0.6 * mid_weight + 0.4 * distance_penalty
        insert_aptness_scores.append(position_aptness)
    mean_aptness = statistics.mean(insert_aptness_scores)
    return max(0.0, min(1.0, mean_aptness))

METRICS = {"insertion_positional_aptness": insertion_positional_aptness}

import math
import re
import numpy as np
from wordfreq import word_frequency
import statistics

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were "
    "be been being it its this that these those i you he she we they me him her us them my your "
    "his their our not no so do does did have has had will would can could should may might must "
    "about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _word_surprisal(word):
    p = word_frequency(word, "en")
    if p > 0:
        return -math.log2(p)
    return 24.0

def _ref_surprisal_stats():
    words = ["the", "and", "to", "of", "a", "in", "is", "was", "he", "it", "i", "that", "you", "she", "for", "with", "be", "at", "this", "by", "from", "or", "have", "had", "as", "they", "are", "been", "will", "can", "said", "new", "good", "first", "time", "very", "after", "only", "back", "some", "just", "than", "know", "even", "think", "other", "there", "about", "us", "them", "my", "your", "his", "her", "its", "our", "their", "so", "go", "come", "make", "take", "see", "give", "find", "tell", "ask", "work", "call", "try", "use", "feel", "become", "leave", "put", "mean", "keep", "let", "begin", "seem", "show", "hear", "turn", "start"]
    ps = np.array([word_frequency(w, "en") for w in words])
    ps = ps[ps > 0]
    ps = ps / ps.sum()
    sur = -np.log2(ps)
    mu = float((ps * sur).sum())
    sd = float(math.sqrt((ps * (sur - mu) ** 2).sum()))
    return mu, sd

_SURP_MU, _SURP_SD = _ref_surprisal_stats()

def rare_word_semantic_gate(text, anchor):
    if not (text and anchor):
        return 0.5
    anchor_content = set(_content(anchor))
    text_content = _content(text)
    if not text_content:
        return 0.5
    gated_surprisals = []
    for word in text_content:
        surp = _word_surprisal(word)
        if surp > _SURP_MU + _SURP_SD:
            overlap_with_anchor = 1.0 if word in anchor_content else 0.0
            gated_surp = (surp - _SURP_MU) / (2.0 * _SURP_SD + 0.1) * (0.5 + 0.5 * overlap_with_anchor)
            gated_surprisals.append(gated_surp)
        else:
            gated_surprisals.append(0.0)
    if gated_surprisals:
        mean_gated = statistics.mean(gated_surprisals)
        return max(0.0, min(1.0, mean_gated * 0.7 + 0.3))
    return 0.3

METRICS = {"rare_word_semantic_gate": rare_word_semantic_gate}
